@inline function _nas_warped_matrix_finite(x::Float64)
    return isfinite(x) ? x : 0.0
end

function _nas_warped_matrix_metrics(coords::AbstractMatrix, Cb)
    e12x = Float64(coords[2, 1] - coords[1, 1])
    e12y = Float64(coords[2, 2] - coords[1, 2])
    e23x = Float64(coords[3, 1] - coords[2, 1])
    e23y = Float64(coords[3, 2] - coords[2, 2])
    e34x = Float64(coords[4, 1] - coords[3, 1])
    e34y = Float64(coords[4, 2] - coords[3, 2])
    e41x = Float64(coords[1, 1] - coords[4, 1])
    e41y = Float64(coords[1, 2] - coords[4, 2])
    l12 = hypot(e12x, e12y)
    l23 = hypot(e23x, e23y)
    l34 = hypot(e34x, e34y)
    l41 = hypot(e41x, e41y)
    lx = max(0.5 * (l12 + l34), 1e-300)
    ly = max(0.5 * (l23 + l41), 1e-300)
    q = max(lx, ly) / max(min(lx, ly), 1e-300)
    alpha = 0.0
    beta = 0.0
    gamma = 0.0
    delta = 0.0
    if Cb !== nothing
        D11 = Float64(Cb[1, 1])
        D22 = Float64(Cb[2, 2])
        D12 = Float64(Cb[1, 2])
        D66 = Float64(Cb[3, 3])
        D16 = Float64(Cb[1, 3])
        D26 = Float64(Cb[2, 3])
        if D11 > 0.0 && D22 > 0.0
            alpha = (ly / lx) * (D11 / D22)^(1.0 / 4.0)
            beta = (D12 + 2.0 * D66) / sqrt(D11 * D22)
            gamma = D16 / ((D11^3 * D22)^(1.0 / 4.0))
            delta = D26 / ((D11 * D22^3)^(1.0 / 4.0))
        end
    end
    return (; q, alpha, beta, gamma, delta)
end

@inline function _nas_warped_matrix_feature_values(m)
    q = max(_nas_warped_matrix_finite(m.q), 1e-300)
    invq = inv(q)
    alpha = _nas_warped_matrix_finite(m.alpha)
    return (
        1.0,
        q,
        q * q,
        invq,
        invq * invq,
        alpha,
        alpha * alpha,
        _nas_warped_matrix_finite(m.beta),
        _nas_warped_matrix_finite(m.gamma),
        _nas_warped_matrix_finite(m.delta),
    )
end

function _nas_warped_matrix_add_component!(K12::AbstractMatrix,
                                           component::Symbol,
                                           resultant::Float64,
                                           values)
    coeff = get(_NAS_WARPED_MATRIX_COEFFS, component, nothing)
    coeff === nothing && return K12
    @inbounds for j in 1:12, i in 1:12
        c = 0.0
        for f in 1:length(values)
            c += coeff[f, i, j] * values[f]
        end
        K12[i, j] += resultant * c
    end
    return K12
end

function geometric_stiffness_quad4_nastran_warped_matrix_synth(coords::AbstractMatrix,
                                                               sigma_mem::AbstractVector,
                                                               h::Float64,
                                                               Cb=nothing)
    Kg = zeros(24, 24)
    h > 1e-30 || return Kg
    metrics = _nas_warped_matrix_metrics(coords, Cb)
    values = _nas_warped_matrix_feature_values(metrics)
    K12 = zeros(12, 12)
    _nas_warped_matrix_add_component!(K12, :nxx, Float64(sigma_mem[1]) * h, values)
    _nas_warped_matrix_add_component!(K12, :nyy, Float64(sigma_mem[2]) * h, values)
    _nas_warped_matrix_add_component!(K12, :nxy, Float64(sigma_mem[3]) * h, values)
    tdofs = (1, 2, 3, 7, 8, 9, 13, 14, 15, 19, 20, 21)
    @inbounds for b in 1:12, a in 1:12
        Kg[tdofs[a], tdofs[b]] = K12[a, b]
    end
    return Kg
end

function geometric_stiffness_quad4_nastran_warped_matrix_synth(coords::AbstractMatrix,
                                                               sigma_mem_gp::AbstractMatrix,
                                                               h::Float64,
                                                               Cb=nothing)
    size(sigma_mem_gp, 2) >= 3 || return zeros(24, 24)
    inv_ngp = 1.0 / max(size(sigma_mem_gp, 1), 1)
    sigma_mem = [
        sum(@view sigma_mem_gp[:, 1]) * inv_ngp,
        sum(@view sigma_mem_gp[:, 2]) * inv_ngp,
        sum(@view sigma_mem_gp[:, 3]) * inv_ngp,
    ]
    return geometric_stiffness_quad4_nastran_warped_matrix_synth(coords, sigma_mem, h, Cb)
end
